 const $=s=>document.querySelector(s);let held=false,chase=null,valveChase=null,operationEnd=null;const clearChase=()=>{chase=null;valveChase=null;world.path=[];world.pending=null;};
 const hud=document.createElement('section');hud.id='combat-hud';hud.hidden=true;hud.setAttribute('aria-label','战斗状态与操作');hud.innerHTML=`<div class="combat-status"><strong id="combat-title"></strong><span id="combat-objective"></span><div id="combat-boss" hidden><b id="combat-boss-label"></b><meter id="combat-boss-health" min="0" max="288"></meter></div><p id="combat-notice" role="status" aria-live="polite"></p><div class="combat-meters"><label>生命 <b id="combat-hp"></b><meter id="combat-health" min="0" max="100"></meter></label><label>耐力 <b id="combat-sp"></b><meter id="combat-stamina" min="0" max="100"></meter></label></div></div><div id="combat-pause" hidden><h2>提灯会等你</h2><p>战斗已暂停。可打开指挥册选择小队、排队下令，恢复后执行。</p><button data-combat="resume">继续战斗</button><button data-combat="retreat">撤回营地，保留调查</button></div><div class="combat-actions"><button data-combat="attack">挥剑 <kbd>空格</kbd></button><button data-combat="dodge">闪避 <kbd>Shift</kbd><small id="combat-dodge"></small></button><button data-combat="pulse">灯光震退 <kbd>Q</kbd><small id="combat-pulse"></small></button><button data-combat="bandage">绷带 <kbd>R</kbd><small id="combat-bandages"></small></button><button data-combat="interact" hidden>关阀 <kbd>E</kbd></button><button data-combat="pause">暂停 / 撤退 <kbd>Esc</kbd></button></div>`;
 const front=document.createElement('aside');front.id='front-panel';front.hidden=true;front.setAttribute('aria-label','防线与小队命令');front.innerHTML=`<div class="front-heading"><h3>水渠指挥册</h3><button id="front-close" aria-label="收起指挥册">×</button></div><div class="front-tabs" role="tablist" aria-label="指挥册页面"><button id="front-tab-build" role="tab" aria-controls="front-build-page" data-tab="build">布防</button><button id="front-tab-squad" role="tab" aria-controls="front-squad-page" data-tab="squad">小队</button></div><p id="front-summary"></p><p id="front-message" role="status"></p><div id="front-build-page" role="tabpanel" aria-labelledby="front-tab-build"><div id="front-facilities"></div><div id="front-build"><p>选择设施 · 开战后固定</p>${FRONT_SLOTS.map(p=>`<label>${p.name}<select aria-label="${p.name}" data-front-slot="${p.id}"><option value="">空地</option><option value="barrier">路障 · 2补给</option><option value="tower">灯塔 · 3补给</option></select></label>`).join('')}</div></div><div id="front-squad-page" role="tabpanel" aria-labelledby="front-tab-squad"><div class="front-squads"><button data-front="select" data-value="shield">盾卫队 · Z</button><button data-front="select" data-value="archer">弩手队 · X</button></div><p id="front-order"></p><div class="front-orders">${[['follow','跟随我'],['pump','守住泵'],['west','西渠旗'],['east','东堤旗']].map(([v,n])=>`<button data-front="order" data-value="${v}">${n}</button>`).join('')}</div></div><button data-front="launch" id="front-launch">发起第一波 · F</button><button data-front="repair" id="front-repair">战地修理 · 3次</button><p class="front-note">每波敌人：5 / 6 / 7 / 8 / 9 / 10<br>两队各3人 · 清场后整备6秒<br>点击队员选队，点击旗帜派遣<br>空格挥剑 · Enter确认面板选项<br>最后清除敌群并夺回双旗</p>`;hud.append(front);const toggle=document.createElement('button');toggle.id='front-toggle';toggle.textContent='指挥册 · C';toggle.setAttribute('aria-controls','front-panel');toggle.hidden=true;hud.append(toggle);toggle.addEventListener('click',()=>panel());front.querySelector('#front-close').addEventListener('click',()=>panel(false));front.querySelectorAll('[data-tab]').forEach(btn=>btn.addEventListener('click',()=>{world.combat.front.panelTab=btn.dataset.tab;renderHUD();}));
 function panel(open,returnToWorld=false){const f=world.combat?.front||world.combat?.operation;if(!f||world.combat.operation&&world.combat.paused)return;f.panelOpen=open??!f.panelOpen;renderHUD();if(!f.panelOpen)(returnToWorld?$('#world'):toggle).focus();}

 front.addEventListener('click',e=>{const t=e.target.closest('[data-front]');if(t){combatCommand(world.combat,s().player,t.dataset.front,t.dataset.value);if(t.dataset.front==='launch'){held=false;clearChase();world.keys.clear();}renderHUD();}});
 front.addEventListener('change',e=>{if(e.target.dataset.frontSlot){combatCommand(world.combat,s().player,'build',{id:e.target.dataset.frontSlot,type:e.target.value||null});renderHUD();}});
 const operationPanel=document.createElement('aside');operationPanel.id='archive-panel';operationPanel.hidden=true;operationPanel.setAttribute('aria-label','封存巡查册');operationPanel.innerHTML='<div class="front-heading"><h3>封存巡查册</h3><button id="archive-panel-close" aria-label="收起巡查册">×</button></div><p id="archive-battle-progress"></p><p id="archive-battle-instructions"></p><button data-combat="operationRepair" id="archive-repair"></button><p class="front-note">空格挥剑 · Q震退 · R绷带<br>移动或受伤会中断关阀<br>C收起本页 · Esc暂停或撤退</p>';hud.append(operationPanel);operationPanel.querySelector('#archive-panel-close').onclick=()=>panel(false);
 $('#game').append(hud);
 const s=()=>getState(),w=()=>s().water;
